estilos.css_firma:
.mo{--tinta:#1d2330;--gris:#4f5766;--cemento:#e2e3e0;--cemento-2:#d5d6d1;--losa:#f7f7f5;--pastina:#c9cac4;--ok:#0d7a5f;--parcial:#9a6f05;--dif:#c0392b;--b-fondo:color-mix(in srgb,var(--apoyo) 12%,#f2f2ef);font-family:"Work Sans",system-ui,sans-serif;background:var(--cemento)}
.sigla{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:27px;letter-spacing:.6px;color:#fff;padding-bottom:4px;border-bottom:3px solid var(--acento)}
.hero{background:var(--losa);border-radius:12px;padding:16px;box-shadow:0 10px 24px -12px rgba(0,0,0,.55),inset 0 0 0 1px rgba(255,255,255,.6)}
.mini{display:grid;grid-template-columns:repeat(5,40px);gap:3px;padding:3px;background:var(--pastina);border-radius:3px;width:max-content}
.pared{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:3px;padding:3px;background:var(--pastina);border-radius:3px}
.cel{background:var(--cemento)}
.cel svg{display:block;width:100%;aspect-ratio:1;animation:poner .7s cubic-bezier(.33,1,.68,1) both}
.lista{background:var(--pastina);border-radius:12px;overflow:hidden;display:grid;gap:2px}
.fila{display:flex;align-items:center;gap:12px;background:var(--losa);padding:11px 14px}
.ind{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) minmax(0,1.6fr);gap:2px;background:var(--pastina);border-radius:12px;overflow:hidden}
.ind > div{background:var(--losa);padding:14px 16px}
.caja{overflow-x:auto;background:var(--pastina);border-radius:12px;padding:2px}
table{border-collapse:separate;border-spacing:0 2px}
th{background:var(--cemento);font-size:11.5px;letter-spacing:.8px;text-transform:uppercase}
td{background:var(--losa);padding:11px 14px}
.barra a.on{color:var(--tinta-acento);background:var(--acento);border-radius:20px}
@keyframes poner{from{opacity:0;scale:.86}to{opacity:1;scale:1}}
/* baldosa (SVG symbol 40x40) */
/* <rect fill=var(--b-fondo)/> cuartos de círculo r13 en las 4 esquinas fill=var(--primario) */
/* <path d="M20 7L33 20L20 33L7 20Z" fill=var(--acento)/> <path d="M20 13L27 20L20 27L13 20Z" fill=var(--b-fondo)/> <circle r=3.2 fill=var(--base)/> */
/* b-parcial: baldosa + triángulo var(--cemento-2) + diagonal var(--parcial) 2px; b-dif: cemento-2 + diagonal var(--dif) 3.2px */
/* guarda: <pattern width=14 height=14><use href=#baldosa/></pattern> en una franja de 14-16px */

.raiz{--ok:#0d7a5f;--rojo:#c0392b;--linea:#dfe3ea;--gris:#566074;--cond:"Barlow Condensed","Arial Narrow",sans-serif;--serif:"Source Serif 4",Georgia,serif;--ease:cubic-bezier(.33,1,.68,1);background:#eef0f3;color:#152238;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
/* duotono: sombras = base, luces = luz del gremio */
.duo{position:relative;overflow:hidden;background:var(--luz);isolation:isolate}
.duo img{display:block;width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.18) brightness(1.06);mix-blend-mode:multiply}
.duo::after{content:"";position:absolute;inset:0;background:var(--base);mix-blend-mode:lighten;pointer-events:none}
.vivo img{animation:kb 22s var(--ease) infinite alternate;transform-origin:62% 40%}
@keyframes kb{from{transform:scale(1.04) translate(0,0)}to{transform:scale(1.16) translate(-3%,-2%)}}
.enc{position:absolute;top:0;left:0;right:0;z-index:5;height:64px;background:linear-gradient(to bottom,color-mix(in srgb,var(--base) 85%,transparent),transparent)}
.sigla{font-family:var(--cond);font-weight:800;font-size:28px;color:#fff;display:flex;flex-direction:column;gap:4px}
.sigla i{display:block;width:28px;height:3px;background:var(--luz);border-radius:2px}
.hero{position:relative;height:500px}
.velo{position:absolute;inset:0;z-index:2;background:linear-gradient(to top,var(--base) 6%,color-mix(in srgb,var(--base) 70%,transparent) 42%,transparent 72%)}
.hola{font-family:var(--cond);font-weight:800;font-size:46px;line-height:.95;text-transform:uppercase}
.quien{font-family:var(--serif);font-style:italic;font-size:15px}
.credito{position:absolute;right:10px;top:70px;font-size:9.5px;writing-mode:vertical-rl}
.banda .duo{position:absolute;top:0;right:0;bottom:0;width:46%;mask-image:linear-gradient(to right,transparent,#000 55%);opacity:.9}
.bajada{font-family:var(--serif);font-style:italic;font-size:16px}
.t-tit{font-family:var(--serif);font-weight:600;font-size:15px}
.scan{height:124px;border-radius:6px;background:#f4f5f7;transform:rotate(-2.5deg);box-shadow:0 10px 24px -12px rgba(0,0,0,.6)}
.scan .hecho{position:absolute;left:0;right:0;bottom:0;border-top:2px solid var(--luz);box-shadow:0 -6px 14px -4px var(--luz);animation:barrido 1.6s var(--ease) both}
@keyframes barrido{from{height:100%}to{height:0%}}
.k b{font-family:var(--cond);font-weight:800;font-size:38px;line-height:1}

.an{font-family:"Archivo",system-ui,sans-serif;font-variation-settings:"wdth" 100;color:#152238;background:#e9edf2}
.sigla{display:flex;align-items:center;gap:9px;color:#fff;font-size:27px}
.sigla i{display:block;width:5px;height:30px;background:var(--acento);border-radius:2px}
.firma{font-variation-settings:"wdth" 70;font-weight:700;font-size:12px;letter-spacing:2.4px}
.cartel{background:color-mix(in srgb,var(--base) 92%,#000);color:#fff;padding:0 16px 18px}
.cartel:before{content:"";display:block;height:8px;margin:0 -16px 16px;background:var(--primario)}
.recorrido{position:relative;margin:18px 16px 4px;height:46px}
.recorrido .via{position:absolute;left:8px;right:8px;top:9px;height:6px;border-radius:3px;background:var(--primario)}
.est{position:absolute;top:0;width:24px;height:24px;margin-left:-12px;border-radius:50%;background:#fff;border:3px solid var(--primario)}
.est.ok{border-color:#0d7a5f}
.est.mal{border-color:#c0392b;background:#c0392b}
.est small{position:absolute;top:28px;left:50%;transform:translateX(-50%);font-size:10px;font-weight:600;color:#5b6478}
.ruta:before{content:"";position:absolute;left:15px;top:22px;bottom:24px;width:7px;border-radius:4px;background:var(--primario)}
.nodo{width:30px;height:30px;border-radius:50%;background:#fff;border:4px solid var(--primario)}
.nodo.term{background:var(--base);border-color:var(--base)}
.demora{padding:2px 8px;border-radius:20px;background:#c0392b;color:#fff;font-size:10.5px;font-weight:800;letter-spacing:.8px;text-transform:uppercase}
.tablero{background:color-mix(in srgb,var(--base) 92%,#000);border-radius:12px;color:#fff}
.tab-cab{border-bottom:2px solid var(--acento)}
.linea{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:"Barlow Condensed";font-weight:700}
.partida{display:grid;grid-template-columns:28px 1fr 64px;gap:10px;animation:flap .5s cubic-bezier(.33,1,.68,1) both;transform-origin:50% 0}
.partida time{font-variation-settings:"wdth" 75;font-weight:600}
@keyframes flap{from{opacity:0;transform:rotateX(-80deg)}to{opacity:1;transform:none}}
.tira a.on{color:#fff;border-bottom:4px solid var(--acento)}
.franja{height:8px;background:var(--primario)}
.ind:before{content:"";position:absolute;left:0;right:0;top:0;height:5px;background:var(--c)}
.ind b{font-family:"Barlow Condensed";font-size:40px;animation:flap .6s cubic-bezier(.33,1,.68,1) both}
.lr .via i:after{content:"";position:absolute;right:-7px;top:-5px;width:18px;height:18px;border-radius:50%;background:#fff;border:4px solid #c0392b}
th{border-bottom:2px solid #152238}

.cr{font-family:"Barlow",system-ui,sans-serif;color:#152238;-webkit-font-smoothing:antialiased}
.enc-gremio{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:27px;letter-spacing:.05em;color:#fff;padding-bottom:4px;border-bottom:2px solid var(--acento)}
.enc-colm{font-family:"Barlow Condensed",sans-serif;font-weight:600;font-size:13px;letter-spacing:.24em}
.micro{font-family:"Barlow Condensed",sans-serif;font-size:6px;font-weight:600;letter-spacing:.14em;white-space:nowrap;overflow:hidden;line-height:8px;text-transform:uppercase}
.banda .guill{position:absolute;right:-120px;top:-70px;width:360px;height:360px;opacity:.5}
.carnet{position:relative;border-radius:14px;height:184px;overflow:hidden;color:#fff;background:color-mix(in srgb,var(--primario) 70%,var(--base));box-shadow:0 1px 0 color-mix(in srgb,#fff 18%,transparent) inset,0 18px 40px -18px rgba(0,0,0,.6);border:1px solid color-mix(in srgb,#fff 14%,transparent)}
.carnet .nombre{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:28px;letter-spacing:.06em}
.carnet .serie{position:absolute;right:16px;top:12px;font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:20px;letter-spacing:.08em;color:var(--acento-txt)}
.holo{position:absolute;right:16px;bottom:16px;width:54px;height:54px;border-radius:50%;background:conic-gradient(from 30deg,color-mix(in srgb,var(--acento) 70%,#fff),#fff,color-mix(in srgb,var(--apoyo) 60%,#fff),color-mix(in srgb,var(--acento) 85%,#fff),#fff,color-mix(in srgb,var(--acento) 70%,#fff));box-shadow:0 0 0 1px rgba(255,255,255,.5) inset,0 3px 10px rgba(0,0,0,.35)}
.hoja{margin:-80px 12px 0;border-radius:12px;background-color:#f6f8fb;background-image:repeating-linear-gradient(118deg,color-mix(in srgb,var(--primario) 5%,transparent) 0 1px,transparent 1px 7px),repeating-linear-gradient(62deg,color-mix(in srgb,var(--apoyo) 6%,transparent) 0 1px,transparent 1px 9px);box-shadow:0 12px 30px -14px rgba(15,25,45,.45),0 0 0 1px rgba(21,34,56,.08)}
.serie,.rc-tit .nro{font-variant-numeric:tabular-nums;font-weight:600;letter-spacing:.06em;color:color-mix(in srgb,var(--primario) 75%,#5b6478)}
.sello{flex:0 0 136px;width:136px;height:136px;rotate:-6deg;animation:estampa .6s .3s cubic-bezier(.33,1,.68,1) both}
@keyframes estampa{0%{opacity:0;scale:1.5;rotate:-20deg}70%{opacity:1;scale:.96;rotate:-5deg}100%{opacity:1;scale:1;rotate:-6deg}}
.v-num{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:54px;line-height:.9}
.tira a.on{background:#fff;color:var(--base);border-radius:20px}
.cel .v{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:38px;color:color-mix(in srgb,var(--primario) 70%,#152238)}
/* JS: guilloché = epitrocoide rosa(R,r,d,s,cx,cy,n): x=cx+s*((R+r)cos t - d cos(k t)), k=(R+r)/r */
/* sello SVG: circle r66 #fff + roseta stroke #c0392b .45 + aros r58/r44 + <textPath> 9.5px tracking 1.6px + círculo r30 rojo con triángulo blanco */

.tl{--tinta:#152238;--rotulo:#5b6478;--ok:#0d7a5f;--dif:#c0392b;--parcial:#b8860b;--desk:color-mix(in srgb,var(--primario) 7%,#eef1f5);--filete:color-mix(in srgb,var(--primario) 16%,#dde3ea);--carbon:color-mix(in srgb,var(--primario) 88%,#000);font-family:"Red Hat Text",system-ui,sans-serif;color:var(--tinta);background:var(--desk)}
.num{font-family:"Red Hat Mono",ui-monospace,monospace;font-variant-numeric:tabular-nums}
.rot{font-size:10.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--rotulo);font-weight:600}
.logo{font-family:"Barlow Condensed";font-weight:700;font-size:25px;letter-spacing:.04em;color:#fff;padding-bottom:4px;border-bottom:3px solid var(--acento)}
.lengueta{height:30px;border-radius:9px 9px 0 0;font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:600}
.lg1{margin:0 26px 0 42px;background:color-mix(in srgb,var(--apoyo) 30%,white)}
.lg2{margin:-8px 12px 0 22px;background:color-mix(in srgb,var(--primario) 18%,white);color:var(--carbon)}
.cupon{background:#fff;border-radius:10px;margin-top:-8px;box-shadow:0 1px 0 var(--filete),0 10px 24px -14px color-mix(in srgb,var(--base) 60%,transparent)}
.sello{font-family:"Barlow Condensed";font-weight:700;font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--dif);border:2px solid currentColor;border-radius:5px;padding:4px 9px 3px;box-shadow:inset 0 0 0 2px #fff,inset 0 0 0 3px currentColor;transform:rotate(-7deg);filter:url(#goma);opacity:.9;animation:estampa .5s cubic-bezier(.33,1,.68,1) .55s both}
@keyframes estampa{0%{opacity:0;transform:rotate(-7deg) scale(1.5)}60%{opacity:.95;transform:rotate(-7deg) scale(.96)}100%{opacity:.9;transform:rotate(-7deg) scale(1)}}
/* <filter id="goma"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2"/><feDisplacementMap in="SourceGraphic" scale="1.6"/></filter> */
.perfo{height:16px;margin:0 10px;background:radial-gradient(circle at 6px 8px,var(--desk) 2.6px,transparent 3.2px) 0 0/12px 16px repeat-x;position:relative}
.perfo::before,.perfo::after{content:"";position:absolute;top:0;width:16px;height:16px;border-radius:50%;background:var(--desk)}
.perfo::before{left:-18px}.perfo::after{right:-18px}
.hoja::before{content:"";position:absolute;left:8px;top:10px;bottom:10px;width:8px;background:radial-gradient(circle at 4px 6px,var(--desk) 2.5px,transparent 3px) 0 0/8px 13px repeat-y}
.hoja::after{content:"";position:absolute;left:22px;top:0;bottom:0;border-left:1px dashed var(--filete)}
.bc .der{width:30px;border-left:1.5px dashed var(--filete)}
.bc .der span{writing-mode:vertical-rl;transform:rotate(180deg);font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}
.troquel .agujeros{position:absolute;left:14px;right:14px;top:9px;height:6px;background:radial-gradient(circle at 3px 3px,var(--desk) 2.6px,transparent 3.1px) 0 0/11px 6px repeat-x}
.talon{background:color-mix(in srgb,var(--primario) 5%,white);border-radius:0 0 10px 10px}
.cup + .cup{background-image:radial-gradient(circle at 3px 4px,var(--desk) 2.4px,transparent 3px);background-size:6px 11px;background-repeat:repeat-y;background-position:-3px 6px}
.st{font-family:"Barlow Condensed";font-weight:700;font-size:13px;letter-spacing:.12em;text-transform:uppercase;border:1.8px solid currentColor;border-radius:4px;padding:2px 7px 1px;box-shadow:inset 0 0 0 1.5px #fff,inset 0 0 0 2.6px currentColor;transform:rotate(-3deg);filter:url(#goma)}
tr.vencida .tt{color:#6b7488;text-decoration:line-through}
.c{padding:10px 18px 12px;border-top:1px solid var(--filete);border-left:1px solid var(--filete)}
.c input.grande{font-family:"Barlow Condensed";font-weight:700;font-size:24px;text-transform:uppercase}

.pu{background:var(--base);color:#fff;font-family:"Hanken Grotesk",system-ui,sans-serif;font-size:14px;line-height:1.45;--tenue:color-mix(in srgb,#fff 66%,var(--base));--filo:color-mix(in srgb,#fff 14%,var(--base));--rojo:#e5533d;--ambar:#d9a520;--verde:#3fb58f}
.sigla{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:26px;letter-spacing:.5px;padding-left:10px;border-left:3px solid var(--acento)}
.enc{height:56px;border-bottom:1px solid var(--filo)}
.rot{font-size:10.5px;letter-spacing:1.6px;text-transform:uppercase;color:var(--tenue);font-weight:600}
.cifra{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:92px;line-height:.8;letter-spacing:-1px;font-variant-numeric:tabular-nums}
.cifra small{font-size:44px;color:var(--tenue);font-weight:600}
.dif i{width:8px;height:8px;border-radius:50%;background:var(--rojo)}
.pulso{position:relative;height:150px}
.pulso .relleno{fill:var(--base)}
.pulso .trazo{fill:none;stroke:#fff;stroke-width:1;stroke-linejoin:round;opacity:.82;stroke-dasharray:900;stroke-dashoffset:900;animation:dibujar 1.4s cubic-bezier(.33,1,.68,1) forwards;animation-delay:var(--d)}
.pulso .trazo.parcial{stroke:var(--ambar);opacity:1}
.pulso .trazo.dif{stroke:var(--rojo);stroke-width:2.2;opacity:1}
.pulso .mes{position:absolute;left:0;font-size:9px;letter-spacing:1px;color:var(--tenue);transform:translateY(-50%);background:var(--base)}
@keyframes dibujar{to{stroke-dashoffset:0}}
.btn{border:0;border-radius:9px;background:var(--acento);color:var(--tinta-acento);font:600 14px "Hanken Grotesk",sans-serif;height:44px;padding:0 20px;transition:scale .12s cubic-bezier(.23,1,.32,1)}
.btn:active{scale:.97}
.lista li{border-bottom:1px solid var(--filo)}
.barra a[aria-current]::before{content:"";position:absolute;top:-1px;left:30%;right:30%;height:2px;background:var(--acento)}
/* escritorio claro */
.cab h1{font-family:"Barlow Condensed",sans-serif;font-weight:700;font-size:60px;line-height:.85;text-transform:uppercase}
.tabs a[aria-current]{color:var(--base);font-weight:600;border-bottom:2px solid var(--acento)}
.cifras{display:flex;flex-wrap:wrap;border-top:1px solid var(--filo);border-bottom:1px solid var(--filo)}
.cifras div{padding:14px 28px 14px 0;margin-right:28px;border-right:1px solid var(--filo)}
.campo input,.campo textarea,.campo select{border:0;border-bottom:1px solid var(--filo2);background:transparent;border-radius:0;padding:6px 0 8px}
.emp .barra::before{content:"";position:absolute;left:0;right:0;top:4px;border-top:1px dotted var(--filo2)}
.emp .barra i::after{content:"";position:absolute;right:-3px;top:-3px;width:9px;height:9px;border-radius:50%;background:var(--base)}
/* JS: cada línea = envolvente gaussiana exp(-c²) × amplitud (11 ok, 18 parcial, 46 dif) + ruido; relleno cierra 40px abajo para tapar las de atrás */
